/**
 * animations.js — Shimeji frame mappings.
 *
 * Supports two sprite sources:
 *   1. Inline sprite data (per-character, from characters.js)
 *   2. URL paths      (single-character, dev-mode fallback to /sprites/)
 *
 * characters.js is auto-generated by `node scripts/inline-sprites.js`.
 * It must exist before building. Run `npm run inline-sprites` if missing.
 */
import * as PIXI from 'pixi.js';
import { DEFAULT_FRAMES } from './characters/characters.js';

/**
 * Build an array of PIXI.Textures from a numbered frame list.
 *
 * Resolution order for each frame:
 *   1. Per-character spriteData[sprite name]  (bundled base64)
 *   2. Dev-mode fallback: `${dir}shime{N}.png` (loads from /sprites/)
 *
 * @param {string}   dir       Public path prefix for dev-mode fallback
 * @param {object}   spriteData Per-character sprite data (filename → data URL)
 * @param {number[]} indices    Frame numbers to load
 * @returns {PIXI.Texture[]}
 */
export function frames(dir, spriteData, indices) {
  return indices.map((i) => {
    const filename = `shime${i}.png`;
    const src = spriteData?.[filename] || `${dir}${filename}`;
    return PIXI.Texture.from(src);
  });
}

/**
 * Build the full animation dictionary for a character.
 *
 * @param {string} [dir='/sprites/']  Dev-mode sprite path prefix
 * @param {object} [spriteData={}]   Per-character sprite data
 * @param {object} [frameMap]        Per-character frame mapping (defaults to DEFAULT_FRAMES)
 * @returns {Record<string, PIXI.Texture[]>}
 */
export function buildAnimations(dir = '/sprites/', spriteData = {}, frameMap) {
  const fm = frameMap || DEFAULT_FRAMES;

  // Each value is a [frame, frame, ...] list pulled from the per-character
  // mapping (or DEFAULT_FRAMES). Characters can override any animation
  // by setting it in their character.json `frames` block.
  const pick = (key) => fm[key] || DEFAULT_FRAMES[key] || [];

  return {
    // ── Standing / Idle ────────────────────────────────────
    idle:  frames(dir, spriteData, pick('idle')),

    // ── Walking ────────────────────────────────────────────
    walk:  frames(dir, spriteData, pick('walk')),

    // ── Crawling (ground) ──────────────────────────────────
    crawl: frames(dir, spriteData, pick('crawl')),

    // ── Wall grab / wall crawl ─────────────────────────────
    grab:  frames(dir, spriteData, pick('grab')),

    // ── Sitting / resting ──────────────────────────────────
    sit:   frames(dir, spriteData, pick('sit')),

    // ── Peek (looping animation shown after avatar walks off-screen) ─
    peek:  frames(dir, spriteData, pick('peek')),

    // ── Greeting / say-hi ──────────────────────────────────
    say_hi: frames(dir, spriteData, pick('say_hi')),

    // ── Wave ───────────────────────────────────────────────
    wave:   frames(dir, spriteData, pick('wave')),

    // ── Ceiling crawl ──────────────────────────────────────
    crawl_top: frames(dir, spriteData, pick('crawl_top')),

    // ── Jump ───────────────────────────────────────────────
    jump: frames(dir, spriteData, pick('jump')),

    // ── Drag interaction ───────────────────────────────────
    held:                 frames(dir, spriteData, pick('held')),
    heldRightFast:        frames(dir, spriteData, pick('heldRightFast')),
    heldRightTransition:  frames(dir, spriteData, pick('heldRightTransition')),
    heldRightStill:       frames(dir, spriteData, pick('heldRightStill')),
    heldLeftFast:         frames(dir, spriteData, pick('heldLeftFast')),
    heldLeftTransition:   frames(dir, spriteData, pick('heldLeftTransition')),
    heldLeftStill:        frames(dir, spriteData, pick('heldLeftStill')),

    // ── Falling / thrown ───────────────────────────────────
    falling: frames(dir, spriteData, pick('falling')),
    land:    frames(dir, spriteData, pick('land')),

    // ── TV Clone ───────────────────────────────────────────
    tv_clone: frames(dir, spriteData, pick('tv_clone')),

    // ── Remove Cap ─────────────────────────────────────────
    remove_cap: frames(dir, spriteData, pick('remove_cap')),

    // ── Summon (one-shot entrance animation) ────────────────
    summon_falling: frames(dir, spriteData, pick('summon_falling')),
    summon_landed:  frames(dir, spriteData, pick('summon_landed')),
  };
}